It uses __eq__ after matching __hash__, so equal objects are treated as the same key.

code:
class P:
    def __init__(self, n):
        self.n = n
    def __hash__(self):
        return hash(self.n)
    def __eq__(self, other):
        return self.n == other.n

d = {P('a'): 1}
print(d[P('a')])  # 1

