For each number, check if target minus the number is already in a seen dict, otherwise store the number with its index.

code:
def two_sum(nums, target):
    seen = {}
    for i, n in enumerate(nums):
        if target - n in seen:
            return [seen[target - n], i]
        seen[n] = i

print(two_sum([2, 7, 11, 15], 9))  # [0, 1]

